<script setup lang="ts">import {ref,onMounted} from 'vue';import {batches} from '../stores/batches';import {canWrite} from '../stores/auth';import {useTask} from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';const name=ref(''),text=ref(''),description=ref('');const {error,busy,act}=useTask();onMounted(batches.load);async function file(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(f)text.value=await f.text()}function submit(){act(async()=>{await batches.create({name:name.value,csv_text:text.value,description:description.value});name.value='';text.value=''})}</script><template><PageHeading index="01 / 对账批次" title="把委托与凭证，留在同一份输入快照。" note="CSV列external_id,side,party,reference,amount_cents,currency,booking_date。方向milestone/receipt，金额只接正整数分，币种CNY，日期YYYY-MM-DD。"/><div class="two-col"><section><Notice :message="batches.error.value"/><article v-for="r in batches.items.value" :key="r.id" class="batch-row"><p class="eyebrow">STATEMENT BATCH</p><h2>{{r.name}}</h2><p>{{r.description}}</p><a :href="'#/items?batch='+r.id" class="action-link">打开委托与凭证分录 →</a></article></section><form v-if="canWrite()" class="editor-panel" @submit.prevent="submit"><h2>导入结算批次</h2><label>批次名称<input v-model="name" required minlength="2"></label><label>CSV文件<input type="file" accept=".csv" @change="file"></label><label>整数分CSV<textarea v-model="text" rows="10" required placeholder="external_id,side,party,reference,amount_cents,currency,booking_date"></textarea></label><label>来源说明<input v-model="description"></label><Notice :message="error"/><button :disabled="busy">校验并导入批次</button></form></div></template>
